# PostGIS geometry point
```
npx drizzle-kit generate --custom
```

```
CREATE EXTENSION postgis;
```

```
import { geometry, index, pgTable, serial, text } from 'drizzle-orm/pg-core';

export const stores = pgTable(
  'stores',
  {
    id: serial('id').primaryKey(),
    name: text('name').notNull(),
    location: geometry('location', { type: 'point', mode: 'xy', srid: 4326 }).notNull(),
  },
  (t) => [\
    index('spatial_index').using('gist', t.location),\
  ]
);
```

```
// mode: 'xy'
await db.insert(stores).values({
  name: 'Test',
  location: { x: -90.9, y: 18.7 },
});

// mode: 'tuple'
await db.insert(stores).values({
  name: 'Test',
  location: [-90.9, 18.7],
});

// sql raw
await db.insert(stores).values({
  name: 'Test',
  location: sql`ST_SetSRID(ST_MakePoint(-90.9, 18.7), 4326)`,
});
```

```
import { getColumns, sql } from 'drizzle-orm';
import { stores } from './schema';

const point = {
  x: -73.935_242,
  y: 40.730_61,
};

const sqlPoint = sql`ST_SetSRID(ST_MakePoint(${point.x}, ${point.y}), 4326)`;

await db
  .select({
    ...getColumns(stores),
    distance: sql`ST_Distance(${stores.location}, ${sqlPoint})`,
  })
  .from(stores)
  .orderBy(sql`${stores.location} <-> ${sqlPoint}`)
  .limit(1);
```

# Custom types
## Examples
#### Integer
```
import { customType, pgTable } from 'drizzle-orm/pg-core';

const customInteger = customType<{ data: number; }>(
  {
    dataType() {
      return 'integer';
    },
  },
);

export const users = pgTable("users", {
  id: customInteger(),
});
```

#### Text
```
import { customType, pgTable } from 'drizzle-orm/pg-core';

const customText = customType<{ data: string }>({
  dataType() {
    return 'text';
  },
});

export const users = pgTable('users', {
  name: customText(),
});
```

#### Timestamp
```
import { customType, pgTable } from 'drizzle-orm/pg-core';

const customTimestamp = customType<{
  data: Date;
  driverData: string;
  config: { withTimezone: boolean; precision?: number };
  configRequired: false;
}>({
  dataType(config) {
    const precision = typeof config?.precision !== 'undefined' ? ` (${config.precision})` : '';
    return `timestamp${precision}${config?.withTimezone ? ' with time zone' : ''}`;
  },
  fromDriver(value: string): Date {
    return new Date(value);
  },
  codec: (config) => {
    if (config?.withTimezone) return 'timestamp with time zone';

    return 'timestamp';
  },
});

export const users = pgTable('users', {
  createdAt: customTimestamp('created_at'),
});
```

```
const usersTable = pgTable('users', {
  id: customInteger().primaryKey(),
  name: customText().notNull(),
  createdAt: customTimestamp('created_at', { withTimezone: true }).notNull()
    .default(sql`now()`),
});
```

## Transform layers and execution order
```
// DB stores as bigint, driver returns string, codec converts to BigInt,
// but you want a number in your app code
const myColumn = customType<{ data: number; driverData: string }>({
  dataType() { return 'bigint'; },
  codec: 'bigint',           // driver "123" → BigInt(123n)
  fromDriver(value) {        // BigInt(123n) → Number(123)
    return Number(value);
  },
});
```

```
// Same result, no fromDriver needed
const myColumn = customType<{ data: number; driverData: string }>({
  dataType() { return 'bigint'; },
  codec: 'bigint:number',    // driver "123" → Number(123) directly
});
```

# Geospatial Polygons: A Full-Stack Guide with PostGIS, Node.js
## Backend Setup with Node.js, NestJS, and Drizzle ORM
```
// database-schema.ts
import { serial, text, pgTable, customType } from 'drizzle-orm/pg-core';
import { Geometry } from 'wkx'; // For WKB to GeoJSON conversion

type Coordinate = [number, number];
interface GeoJson {
  type: string;
  coordinates: Coordinate[][];
}
const polygon = customType<{
  data: Coordinate[][];
  driverData: string;
}>({
  dataType() {
    return 'geometry(Polygon, 4326)'; // Define the PostGIS geometry type with SRID
  },
  toDriver(coordinates: Coordinate[][]): string {
    // Convert array coordinates to GeoJSON string for database insertion
    return JSON.stringify({
      type: 'Polygon',
      coordinates,
    });
  },
  fromDriver(data: string): Coordinate[][] {
    // Convert WKB (Well-Known Binary) from DB back to GeoJSON coordinates for application
    const geoJson = Geometry.parse(Buffer.from(data, 'hex')).toGeoJSON() as GeoJson;
    return geoJson.coordinates;
  },
});
export const areas = pgTable('areas', {
  id: serial('id').primaryKey(),
  name: text('name').notNull(),
  polygon: polygon('polygon').notNull(),
});
export const databaseSchema = { areas };
```

### Implementing Overlap Prevention on the Backend
```
// areas.service.ts (simplified)
import { Injectable, BadRequestException } from '@nestjs/common';
import { DrizzleService } from '../database/drizzle.service';
import { databaseSchema } from '../database/database-schema';
import { sql } from 'drizzle-orm';

@Injectable()
export class AreasService {
  constructor(private readonly drizzleService: DrizzleService) {}
  async create(area: AreaDto) {
    const newPolygonGeoJson = JSON.stringify({ type: 'Polygon', coordinates: area.polygon });
    const overlapCheckResult = await this.drizzleService.db.execute(sql`
        SELECT EXISTS (
            SELECT 1
            FROM ${databaseSchema.areas}
            WHERE polygon && ST_GeomFromGeoJSON(${newPolygonGeoJson})
            AND ST_Relate(polygon, ST_GeomFromGeoJSON(${newPolygonGeoJson}), '2********')
        ) AS "hasOverlap";
    `);
    if (overlapCheckResult.rows?.hasOverlap) {
      throw new BadRequestException('The new polygon overlaps with an existing area.');
    }
    const createdAreas = await this.drizzleService.db
      .insert(databaseSchema.areas)
      .values({
        name: area.name,
        polygon: area.polygon, // Uses the custom type's toDriver method
      })
      .returning();
    return createdAreas.pop();
  }
}
```
